// ============================================================
// Correspondência flexível de nomes:
// Ignora maiúsculas/minúsculas, acentos e apelidos entre parênteses
// Ex: "Raubustt (Arroz)" == "raubustt" == "RAUBUSTT"
// Ex: "Gabriel (Dodoi)" == "dodoi" == "gabriel"
// ============================================================
const normNome = (nome) => {
  if (!nome) return '';
  return nome.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
};
// Extrai todas as "partes" de um nome: nome principal + apelidos entre parênteses
const partesNome = (nome) => {
  const norm = normNome(nome);
  // Captura o nome principal (antes do parêntese) e os apelidos dentro dos parênteses
  const partes = [norm.replace(/\s*\(.*?\)/g,'').trim()];
  const matches = norm.match(/\(([^)]+)\)/g);
  if (matches) matches.forEach(m => partes.push(m.replace(/[()]/g,'').trim()));
  return partes.filter(Boolean);
};
// Retorna true se dois nomes "combinam" por qualquer parte
const nomesBatem = (nomeA, nomeB) => {
  const partesA = partesNome(nomeA);
  const partesB = partesNome(nomeB);
  return partesA.some(a => partesB.some(b => a === b || a.startsWith(b) || b.startsWith(a)));
};
// Encontra contato pelo nome (flexível)
const encontrarContato = (contatos, nome) =>
  contatos.find(c => nomesBatem(c.nome, nome));
// Filtra contatos cujo nome bate com algum da lista (flexível)
const filtrarContatosPorNomes = (contatos, nomes) =>
  contatos.filter(c => nomes.some(n => nomesBatem(c.nome, n)));
