const enviarLembreteZAPI = async (telefone, mensagem) => {
  try {
    const num = telefone.replace(/\D/g,'');
    const numFmt = num.startsWith('55') ? num : '55'+num;
    // Tenta Evolution API primeiro
    try {
      const resp = await fetch(`${EVOLUTION_URL}/message/sendText/${EVOLUTION_INSTANCE}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': EVOLUTION_APIKEY
        },
        body: JSON.stringify({ number: numFmt, text: mensagem })
      });
      if (resp.ok) return;
    } catch(e) { console.log('Evolution API offline, usando fallback'); }
    // Fallback: abre WhatsApp Web com a mensagem
    window.open(`https://wa.me/${numFmt}?text=${encodeURIComponent(mensagem)}`, '_blank');
  } catch(e) { console.log('Erro WhatsApp:', e); }
};

