const enviarLembretesJogo = async (jogo, contatos) => {
  if (!contatos || contatos.length === 0) return;
  const dataFmt = jogo.data
    ? new Date(jogo.data+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit'})
    : jogo.data;
  for (const contato of contatos) {
    if (!contato.telefone) continue;
    const msg =
      `🏐 *Volei Tche - Convocação!*\n\n` +
      `Ola *${contato.nome}*!\n\n` +
      (jogo.adversario ? `*Volei Tche* 🆚 *${jogo.adversario}*\n━━━━━━━━━━━━━━━━\n` : '') +
      `🏐 ${jogo.modalidade}\n` +
      `📅 ${dataFmt} as ${jogo.hora}\n` +
      `📍 ${jogo.local||'A confirmar'}\n` +
      (jogo.recado ? `\n💬 ${jogo.recado}\n` : '') +
      `\nConfirme sua presença:\n` +
      `${BASE_URL}?jogo=${jogo.id}\n\n` +
      `👆 Clique no link acima!`;
    await enviarLembreteZAPI(contato.telefone, msg);
  }
};
