// eslint-disable-next-line no-unused-vars
const enviarParaTodosCallMeBot = async (jogadoresSel, mensagem, contatos) => {
  for (const nome of jogadoresSel) {
    const apikeyEntry = Object.entries(CALLMEBOT_APIKEYS).find(([k]) => nomesBatem(k, nome));
    const apikey = apikeyEntry ? apikeyEntry[1] : undefined;
    if (!apikey) continue;
    const contato = encontrarContato(contatos, nome);
    if (!contato?.telefone) continue;
    await enviarCallMeBot(contato.telefone, apikey, mensagem);
    await new Promise(r => setTimeout(r, 600));
  }
};
