function Carrossel({ fotos: fotosProp }) {
  const [fotosDB, setFotosDB] = useState(null);
  const [idx, setIdx] = useState(0);
  const [zoom, setZoom] = useState(false);

  useEffect(() => {
    getDocs(collection(db,'configuracoes')).then(snap => {
      const cfg = snap.docs.find(d=>d.id==='carousel');
      if (cfg) {
        // Novo formato: fotosUrls = [{url, publicId}]
        if (cfg.data().fotosUrls && cfg.data().fotosUrls.length > 0) {
          setFotosDB(cfg.data().fotosUrls.map(f => typeof f === 'string' ? f : f.url));
        // Formato antigo: fotos = [url, url, ...]
        } else if (cfg.data().fotos && cfg.data().fotos.length > 0) {
          setFotosDB(cfg.data().fotos);
        }
      }
    }).catch(()=>{});
  }, []);

  const fotos = fotosDB || fotosProp;

  useEffect(() => {
    if (!fotos || fotos.length === 0) return;
    const t = setInterval(() => setIdx(i => (i+1) % fotos.length), 3500);
    return () => clearInterval(t);
  }, [fotos]);

  if (!fotos || fotos.length === 0) return null;

  return (
    <div style={{position:'relative',width:'100%',overflow:'hidden',borderRadius:'14px',userSelect:'none'}}>
      <div style={{display:'flex',transition:'transform 0.5s ease',transform:`translateX(-${idx*100}%)`}}>
        {fotos.map((f,i)=>(
          <img key={i} src={f} alt={`foto${i+1}`} onClick={()=>setZoom(true)}
            style={{minWidth:'100%',width:'100%',height:'200px',objectFit:'cover',cursor:'pointer',flexShrink:0}}/>
        ))}
      </div>
      <div style={{position:'absolute',bottom:'8px',left:0,right:0,display:'flex',justifyContent:'center',gap:'5px'}}>
        {fotos.map((_,i)=>(
          <div key={i} onClick={()=>setIdx(i)} style={{width:i===idx?'18px':'6px',height:'6px',borderRadius:'99px',background:i===idx?'#c9a84c':'rgba(255,255,255,0.5)',transition:'all 0.3s',cursor:'pointer'}}/>
        ))}
      </div>
      <button onClick={()=>setIdx(i=>(i-1+fotos.length)%fotos.length)} style={{position:'absolute',left:'6px',top:'50%',transform:'translateY(-50%)',background:'rgba(0,0,0,0.4)',color:'#fff',border:'none',borderRadius:'50%',width:'28px',height:'28px',fontSize:'14px',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center'}}>‹</button>
      <button onClick={()=>setIdx(i=>(i+1)%fotos.length)} style={{position:'absolute',right:'6px',top:'50%',transform:'translateY(-50%)',background:'rgba(0,0,0,0.4)',color:'#fff',border:'none',borderRadius:'50%',width:'28px',height:'28px',fontSize:'14px',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center'}}>›</button>
      {zoom && (
        <div onClick={()=>setZoom(false)} style={{position:'fixed',top:0,left:0,right:0,bottom:0,background:'rgba(0,0,0,0.92)',display:'flex',alignItems:'center',justifyContent:'center',zIndex:9999}}>
          <img src={fotos[idx]} alt="zoom" style={{maxWidth:'100%',maxHeight:'90vh',objectFit:'contain',borderRadius:'8px'}}/>
          <div style={{position:'absolute',top:'16px',right:'16px',color:'#fff',fontSize:'24px',cursor:'pointer'}}>✕</div>
        </div>
      )}
    </div>
  );
}

function GerenciarCarrossel({ onVoltar }) {
  const [fotos, setFotos] = useState([]);
  const [salvando, setSalvando] = useState(false);
  const [load, setLoad] = useState(true);
  const [progresso, setProgresso] = useState('');

  useEffect(() => {
    getDocs(collection(db,'configuracoes')).then(async snap => {
      const cfg = snap.docs.find(d=>d.id==='carousel');
      if (cfg) {
        const data = cfg.data();
        // Novo formato com URLs do Cloudinary
        if (data.fotosUrls && data.fotosUrls.length > 0) {
          // Filtra apenas URLs reais (não base64)
          const apenasUrls = data.fotosUrls.filter(f => {
            const url = typeof f === 'string' ? f : f.url;
            return url && !url.startsWith('data:');
          });
          setFotos(apenasUrls);
        } else if (data.fotos && data.fotos.length > 0) {
          // Formato antigo — filtra base64, mantém só URLs reais
          const apenasUrls = data.fotos
            .filter(u => u && !u.startsWith('data:'))
            .map(u => ({ url: u, publicId: null }));
          setFotos(apenasUrls);
          // Limpa o documento antigo automaticamente se tinha base64
          if (data.fotos.some(u => u && u.startsWith('data:'))) {
            await setDoc(doc(db,'configuracoes','carousel'), {
              fotosUrls: apenasUrls,
              fotos: apenasUrls.map(f=>f.url),
              atualizadoEm: new Date().toISOString()
            });
          }
        }
      }
      setLoad(false);
    }).catch(()=>{ setLoad(false); });
  }, []);

  const addFotos = async (e) => {
    const files = Array.from(e.target.files);
    e.target.value = '';
    setSalvando(true);

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setProgresso(`Enviando foto ${i+1} de ${files.length}...`);

      // Comprime antes de enviar
      const blob = await new Promise(resolve => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX = 1200;
          let w = img.width, h = img.height;
          if (w > MAX || h > MAX) {
            if (w > h) { h = Math.round(h * MAX / w); w = MAX; }
            else { w = Math.round(w * MAX / h); h = MAX; }
          }
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          URL.revokeObjectURL(url);
          canvas.toBlob(b => resolve(b), 'image/jpeg', 0.82);
        };
        img.src = url;
      });

      try {
        const formData = new FormData();
        formData.append('file', blob);
        formData.append('upload_preset', CLOUDINARY_PRESET);
        formData.append('folder', 'carousel');

        const res = await fetch(CLOUDINARY_URL, { method:'POST', body: formData });
        const data = await res.json();

        if (data.secure_url) {
          setFotos(f => [...f, { url: data.secure_url, publicId: data.public_id }]);
        } else {
          const erroMsg = data.error?.message || JSON.stringify(data);
          console.error('Cloudinary erro:', erroMsg);
          // Tenta detectar erro de preset não configurado
          if (erroMsg.includes('preset') || erroMsg.includes('upload_preset')) {
            alert('Erro: Upload preset não encontrado. Verifique se o preset "volei-tche-carousel" está como Unsigned no Cloudinary.');
          } else if (erroMsg.includes('credit') || erroMsg.includes('limit') || erroMsg.includes('storage') || erroMsg.includes('quota')) {
            alert('Limite do Cloudinary atingido. Acesse cloudinary.com para verificar seu plano.');
          } else {
            alert('Erro ao enviar foto: ' + erroMsg);
          }
        }
      } catch(err) {
        alert('Erro ao enviar foto: ' + err.message);
      }
    }

    setProgresso('');
    setSalvando(false);
  };

  const remover = (i) => setFotos(f => f.filter((_,ix)=>ix!==i));

  const mover = (i, dir) => {
    const nova = [...fotos];
    const j = i + dir;
    if (j < 0 || j >= nova.length) return;
    [nova[i], nova[j]] = [nova[j], nova[i]];
    setFotos(nova);
  };

  const salvar = async () => {
    setSalvando(true);
    setProgresso('Salvando...');
    try {
      await setDoc(doc(db,'configuracoes','carousel'), {
        fotosUrls: fotos,
        fotos: fotos.map(f => typeof f === 'string' ? f : f.url), // só URLs, nunca base64
        atualizadoEm: new Date().toISOString()
      });
      alert('Fotos salvas! O carrossel ja foi atualizado para todos.');
    } catch(e) { alert('Erro ao salvar: '+e.message); }
    setProgresso('');
    setSalvando(false);
  };

  if (load) return <div style={{padding:'24px',textAlign:'center',color:'#666'}}>Carregando...</div>;

  return (
    <div style={{padding:'16px'}}>
      <div style={{background:'#fff',borderRadius:'14px',padding:'16px',border:'0.5px solid #ddd',marginBottom:'12px'}}>
        <div style={{fontSize:'14px',fontWeight:'600',color:'#333',marginBottom:'4px'}}>🖼️ Fotos do carrossel</div>
        <div style={{fontSize:'12px',color:'#666',marginBottom:'14px'}}>Sem limite de fotos — armazenadas gratuitamente no Cloudinary.</div>

        {fotos.length === 0 && (
          <div style={{textAlign:'center',padding:'20px',color:'#999',fontSize:'13px',background:'#f9f9f9',borderRadius:'10px',marginBottom:'12px'}}>
            Nenhuma foto ainda. Adicione abaixo!
          </div>
        )}

        <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'8px',marginBottom:'12px'}}>
          {fotos.map((f,i)=>(
            <div key={i} style={{position:'relative',borderRadius:'10px',overflow:'hidden',border:'1px solid #ddd'}}>
              <img src={f.url} alt={`f${i}`} style={{width:'100%',height:'90px',objectFit:'cover',display:'block'}}/>
              <div style={{position:'absolute',top:'4px',right:'4px',display:'flex',gap:'3px'}}>
                <button onClick={()=>mover(i,-1)} disabled={i===0||salvando} style={{background:'rgba(0,0,0,0.55)',color:'#fff',border:'none',borderRadius:'4px',padding:'2px 6px',fontSize:'12px',cursor:'pointer',opacity:i===0?0.3:1}}>↑</button>
                <button onClick={()=>mover(i,1)} disabled={i===fotos.length-1||salvando} style={{background:'rgba(0,0,0,0.55)',color:'#fff',border:'none',borderRadius:'4px',padding:'2px 6px',fontSize:'12px',cursor:'pointer',opacity:i===fotos.length-1?0.3:1}}>↓</button>
                <button onClick={()=>remover(i)} disabled={salvando} style={{background:'rgba(226,75,74,0.85)',color:'#fff',border:'none',borderRadius:'4px',padding:'2px 6px',fontSize:'12px',cursor:'pointer'}}>✕</button>
              </div>
              <div style={{position:'absolute',bottom:'3px',left:'6px',background:'rgba(0,0,0,0.5)',color:'#fff',fontSize:'9px',borderRadius:'3px',padding:'1px 5px'}}>{i+1}</div>
            </div>
          ))}
        </div>

        {progresso ? (
          <div style={{textAlign:'center',padding:'12px',fontSize:'13px',color:'#c9a84c',background:'#f9f9f9',borderRadius:'10px',marginBottom:'10px'}}>
            ⏳ {progresso}
          </div>
        ) : (
          <label style={{display:'block',width:'100%',padding:'11px',background:'#f5f5f5',border:'1.5px dashed #ddd',borderRadius:'10px',textAlign:'center',fontSize:'13px',color:'#666',cursor:'pointer',boxSizing:'border-box',marginBottom:'10px'}}>
            + Adicionar fotos ({fotos.length} salvas)
            <input type="file" accept="image/*" multiple style={{display:'none'}} onChange={addFotos} disabled={salvando}/>
          </label>
        )}

        <button onClick={salvar} disabled={salvando||fotos.length===0} style={{width:'100%',padding:'13px',background:'#0e1e12',color:'#c9a84c',border:'none',borderRadius:'12px',fontSize:'14px',fontWeight:'600',cursor:'pointer',opacity:fotos.length===0?0.4:1,boxSizing:'border-box'}}>
          {salvando ? progresso||'Aguarde...' : 'Salvar ordem das fotos'}
        </button>
      </div>
    </div>
  );
}

