function App() {
  const [tela, setTela] = useState('home');
  const [, setUsuario] = useState(null);
  const [jogadorPerfil, setJogadorPerfil] = useState('');
  const [splash, setSplash] = useState(true);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('darkMode') === 'true');
  const [fotosJogadores, setFotosJogadores] = useState({});

  useEffect(() => {
    // Verifica parametros na URL — funciona ao abrir pelo PWA ou notificacao
    const verificarUrl = () => {
      const p = new URLSearchParams(window.location.search);
      const hash = window.location.hash;
      // Suporte a hash-based routing para PWA
      const hashParams = new URLSearchParams(hash.replace('#','').replace('/?','').replace('/',''));
      const jogoId = p.get('jogo') || p.get('j') || hashParams.get('jogo') || hashParams.get('j');
      const mvpId  = p.get('mvp') || hashParams.get('mvp');
      if (jogoId) { setSplash(false); setTela('confirmar'); return true; }
      if (mvpId)  { setSplash(false); setTela('votarmvp');  return true; }
      return false;
    };
    if (verificarUrl()) return;

    // Se o jogador já é conhecido (visitou antes), verifica pendências e
    // pula direto para a tela de confirmação "Vai jogar? Sim/Não"
    const verificarPendenciaJogador = async () => {
      const meuNome = localStorage.getItem('meu_nome');
      if (!meuNome) return false;
      try {
        const snap = await getDocs(collection(db,'jogos'));
        const hojeStr = new Date().toISOString().split('T')[0];
        const pendente = snap.docs
          .map(d => ({ id: d.id, ...d.data() }))
          .filter(j => !j.excluido && !j.cancelado && j.data >= hojeStr && (j.jogadores||[]).includes(meuNome))
          .sort((a,b) => new Date(a.data) - new Date(b.data))
          .find(j => {
            const conf = j.confirmacoes?.[meuNome];
            return !conf || conf === 'pendente';
          });
        if (pendente) {
          window.history.replaceState({}, '', '?jogo=' + pendente.id);
          setSplash(false);
          setTela('confirmar');
          return true;
        }
      } catch(e) { console.log('Erro ao verificar pendencia:', e.message); }
      return false;
    };

    // Timeout de segurança: nunca deixa a tela em branco por mais de 3s
    const segurancaTimer = setTimeout(() => setSplash(false), 3000);

    verificarPendenciaJogador().then(foiRedirecionado => {
      clearTimeout(segurancaTimer);
      if (foiRedirecionado) return;
      // Tenta novamente após 500ms (caso PWA demore para passar a URL)
      setTimeout(() => { verificarUrl(); }, 500);
      setTimeout(() => setSplash(false), 800);
    }).catch(() => {
      clearTimeout(segurancaTimer);
      setSplash(false);
    });

    const carregarFotos = () => {
      getDocs(collection(db,'perfis')).then(snap => {
        const fotos = {};
        const norm = s => s ? s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim() : '';
        const semParenteses = s => s ? s.replace(/\s*\(.*?\)/g,'').trim() : '';
        snap.docs.forEach(d => {
          const data = d.data();
          if (data.nome && data.fotos && data.fotos.length > 0) {
            const foto = data.fotos[0];
            const nome = data.nome;
            fotos[nome] = foto;                           // "Raubustt"
            fotos[norm(nome)] = foto;                     // "raubustt"
            fotos[semParenteses(nome)] = foto;            // sem apelido
            fotos[norm(semParenteses(nome))] = foto;      // normalizado sem apelido
          }
        });
        setFotosJogadores(fotos);
      });
    };

    carregarFotos();

    // Auto-refresh a cada 30 segundos
    const intervalo = setInterval(() => {
      carregarFotos();
    }, 30000);

    // Detectar nova versao do service worker
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        window.location.reload();
      });
    }

    // Atualizar quando voltar para o app (usuario sai e volta)
    const handleVisibilidade = () => {
      if (document.visibilityState === 'visible') {
        carregarFotos();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilidade);

    return () => {
      clearInterval(intervalo);
      document.removeEventListener('visibilitychange', handleVisibilidade);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem('darkMode', darkMode);
    document.body.classList.toggle('dark', darkMode);
  }, [darkMode]);

  if (splash) return <Splash />;

  return (
    <div className="app" style={{width:'100%',maxWidth:'100vw',minHeight:'100vh',overflowX:'hidden',boxSizing:'border-box'}}>
      {tela === 'home'      && <Home setTela={setTela} darkMode={darkMode} setDarkMode={setDarkMode} fotosJogadores={fotosJogadores} />}
      {tela === 'jogador'   && <AreaJogador setTela={setTela} setJogadorPerfil={setJogadorPerfil} fotosJogadores={fotosJogadores} />}
      {tela === 'agenda'    && <Agenda setTela={setTela} setJogadorPerfil={setJogadorPerfil} fotosJogadores={fotosJogadores} />}
      {tela === 'instalar'  && <Instalar setTela={setTela} />}
      {tela === 'login'     && <Login setTela={setTela} setUsuario={setUsuario} />}
      {tela === 'painel'    && <Painel setTela={setTela} setUsuario={setUsuario} fotosJogadores={fotosJogadores} />}
      {tela === 'confirmar' && <Confirmar />}
      {tela === 'votarmvp'  && <VotarMVP setTela={setTela} />}
      {tela === 'perfil'    && <Perfil setTela={setTela} jogadorNome={jogadorPerfil} />}
      {tela === 'desafio'   && <Desafio setTela={setTela} />}
      {tela === 'galeria'   && <Galeria setTela={setTela} />}
      {tela === 'torneio'   && <Torneio setTela={setTela} />}
    </div>
  );
}

/*  CONFETES  */
function Confetes() {
  const canvasRef = React.useRef(null);
  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    canvas.width  = window.innerWidth;
    canvas.height = window.innerHeight;
    const cores = ['#c9a84c','#f0d080','#27500A','#fff','#E24B4A','#4CAF50','#FFD700'];
    const particulas = Array.from({ length: 120 }, () => ({
      x:  Math.random() * canvas.width,
      y: -Math.random() * canvas.height * 0.5,
      r:  3 + Math.random() * 5,
      cor: cores[Math.floor(Math.random() * cores.length)],
      vel: 2 + Math.random() * 4,
      giro: (Math.random() - 0.5) * 0.2,
      angulo: Math.random() * Math.PI * 2,
      oscilacao: (Math.random() - 0.5) * 2,
    }));
    let raf;
    const animar = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particulas.forEach(p => {
        p.y      += p.vel;
        p.x      += p.oscilacao;
        p.angulo += p.giro;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.angulo);
        ctx.fillStyle = p.cor;
        ctx.fillRect(-p.r / 2, -p.r / 2, p.r, p.r * 1.8);
        ctx.restore();
      });
      raf = requestAnimationFrame(animar);
    };
    animar();
    return () => cancelAnimationFrame(raf);
  }, []);
  return (
    <div style={{
      position:'fixed', inset:0, zIndex:9998,
      pointerEvents:'none',
      animation:'fadeOutConfetes 4.5s forwards',
    }}>
      <div style={{
        position:'absolute', top:'30%', left:'50%',
        transform:'translate(-50%,-50%)',
        fontSize:'80px',
        animation:'popTrofeu 0.5s cubic-bezier(.175,.885,.32,1.275)',
        textAlign:'center',
        filter:'drop-shadow(0 8px 24px rgba(201,168,76,0.7))',
      }}>🏆</div>
      <div style={{
        position:'absolute', top:'calc(30% + 60px)', left:'50%',
        transform:'translateX(-50%)',
        color:'#c9a84c', fontSize:'22px', fontWeight:'800',
        textShadow:'0 2px 12px rgba(0,0,0,0.8)',
        textAlign:'center', whiteSpace:'nowrap',
        animation:'fadeInTxt 0.6s 0.3s both',
      }}>VITÓRIA! 🎉</div>
      <canvas ref={canvasRef} style={{position:'absolute',inset:0,width:'100%',height:'100%'}} />
      <style>{`
        @keyframes fadeOutConfetes { 0%,80%{opacity:1} 100%{opacity:0} }
        @keyframes popTrofeu { from{transform:translate(-50%,-50%) scale(0)} to{transform:translate(-50%,-50%) scale(1)} }
        @keyframes fadeInTxt { from{opacity:0;transform:translateX(-50%) translateY(10px)} to{opacity:1;transform:translateX(-50%) translateY(0)} }
      `}</style>
    </div>
  );
}

