const VAPID_KEY = 'BHCPMoCoZ0JzjXdgtdPT3fEr7DfJ2mS0qsrFpheu4rcPZN4F9NjCUwW0EUccB7RDpQcK0D18qg5SOZOrqf7snuU';

const registrarTokenFCM = async (nomeJogador) => {
  try {
    if (!('Notification' in window)) return;
    if (!('serviceWorker' in navigator)) return;
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') return;
    const swReg = await navigator.serviceWorker.register('/volei-tche/firebase-messaging-sw.js');
    await navigator.serviceWorker.ready;
    const { getMessaging, getToken } = await import('firebase/messaging');
    const messaging = getMessaging();
    const fcmToken = await getToken(messaging, { vapidKey: VAPID_KEY, serviceWorkerRegistration: swReg });
    if (fcmToken && nomeJogador) {
      // Salva/atualiza token no Firestore
      const snap = await getDocs(collection(db, 'tokens'));
      const existente = snap.docs.find(d => d.data().nome === nomeJogador);
      if (existente) {
        await updateDoc(doc(db, 'tokens', existente.id), { token: fcmToken, atualizadoEm: new Date().toISOString() });
      } else {
        await addDoc(collection(db, 'tokens'), { token: fcmToken, nome: nomeJogador, atualizadoEm: new Date().toISOString() });
      }
      console.log('Token FCM registrado para:', nomeJogador);
    }
  } catch(e) { console.log('FCM nao disponivel:', e.message); }
};

// Envia push via Firebase Cloud Messaging para lista de jogadores
const enviarPushParaJogadores = async (jogadoresSel, titulo, corpo, urlDestino) => {
  try {
    // Busca tokens dos jogadores convocados
    const snap = await getDocs(collection(db, 'tokens'));
    const tokens = snap.docs
      .map(d => d.data())
      .filter(d => jogadoresSel.includes(d.nome) && d.token)
      .map(d => d.token);

    if (tokens.length === 0) return;

    // Salva notificação pendente no Firestore para o SW processar
    // (O envio real precisa de Firebase Functions — aqui salvamos para consulta)
    await addDoc(collection(db, 'notificacoes'), {
      tokens,
      titulo,
      corpo,
      url: urlDestino || BASE_URL,
      enviadoEm: new Date().toISOString(),
      status: 'pendente'
    });

    // Notificação local imediata para quem está com o app aberto
    if (Notification.permission === 'granted') {
      new Notification(titulo, {
        body: corpo,
        icon: '/volei-tche/logo192.png',
        badge: '/volei-tche/logo192.png'
      });
    }
  } catch(e) { console.log('Push erro:', e.message); }
};


